#!/usr/bin/env node
// Sound for the motion demo: voiceover lines placed on the timeline, synthesized UI sounds for every beat,
// and a soft pad that ducks under the voice. Everything is generated by ffmpeg; no audio files are needed
// beyond the voice lines from story/audio/make-vo.py.
//
//   node story/render/audio.mjs --plan              # where each voice line lands, and any overlap
//   node story/render/audio.mjs                     # mux audio into story/out/*.mp4 (video copied, not re-encoded)
//   node story/render/audio.mjs --only=vertical
//
// Cues (story/audio/vo-lines.json) point at script.json events: {type:"message",id}, {type:"caption"|"jump"|"chapter",match},
// {type:"stat"|"dm"|"pulse",index}, {type:"end"}; `offset` (ms) shifts the line from the event.
import { createRequire } from 'node:module';
import { spawnSync } from 'node:child_process';
import { existsSync, readFileSync, renameSync, unlinkSync } from 'node:fs';
import { join, resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import os from 'node:os';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const args = Object.fromEntries(process.argv.slice(2).map((a) => { const m = /^--([^=]+)(?:=(.*))?$/.exec(a); return m ? [m[1], m[2] ?? true] : [a, true]; }));

const script = JSON.parse(readFileSync(join(ROOT, 'motion', 'script.json'), 'utf8'));
const spec = JSON.parse(readFileSync(join(ROOT, 'audio', 'vo-lines.json'), 'utf8'));
const durations = JSON.parse(readFileSync(join(ROOT, 'audio', 'vo-durations.json'), 'utf8'));
const ev = script.events.slice().sort((a, b) => a.t - b.t);
const TOTAL = script.meta.duration;
const byType = (t) => ev.filter((e) => e.type === t);

function cueTime(c) {
  const has = (e) => String(e.text || e.title || '').toLowerCase().includes(String(c.match || '').toLowerCase());
  switch (c.type) {
    case 'message': return ev.find((e) => e.type === 'message' && e.id === c.id)?.t;
    case 'caption': case 'jump': case 'chapter': return byType(c.type).find(has)?.t;
    case 'stat': case 'dm': case 'pulse': return byType(c.type)[c.index || 0]?.t;
    case 'end': return byType('end')[0]?.t;
    case 'title': return byType('title')[0]?.t ?? 0;
    default: throw new Error('unknown cue type ' + c.type);
  }
}

const lines = spec.lines.map((l) => {
  const base = cueTime(l.cue);
  if (base == null) throw new Error(`cue not found for ${l.id}: ${JSON.stringify(l.cue)}`);
  const start = Math.max(0, base + (l.offset || 0));
  const dur = Math.round((durations[l.id] || 0) * 1000);
  return { ...l, start, end: start + dur, file: join(ROOT, 'audio', 'vo', `${l.id}.mp3`) };
});

if (args.plan) {
  const chapters = byType('chapter');
  for (let i = 0; i < lines.length; i++) {
    const l = lines[i], n = lines[i + 1];
    const nextChap = chapters.find((c) => c.t > l.start);
    const flags = [];
    if (n && n.start < l.end) flags.push(`OVERLAPS next by ${((l.end - n.start) / 1000).toFixed(1)}s`);
    if (nextChap && nextChap.t < l.end) flags.push(`runs ${((l.end - nextChap.t) / 1000).toFixed(1)}s into "${nextChap.text}"`);
    if (l.end > TOTAL) flags.push('past the end');
    console.log(`${l.id}  ${(l.start / 1000).toFixed(1).padStart(5)} → ${(l.end / 1000).toFixed(1).padStart(5)}  ${flags.join('; ')}  ${l.text}`);
  }
  console.log(`video ${(TOTAL / 1000).toFixed(1)}s`);
  process.exit(0);
}

function findFfmpeg() {
  if (process.env.FFMPEG) return process.env.FFMPEG;
  const TMP = join(os.homedir(), 'AppData', 'Local', 'Temp');
  const tools = ['homi-story-tools', 'otto-story-tools'].map((d) => join(TMP, d)).find((d) => existsSync(join(d, 'node_modules')));
  if (tools) { try { return createRequire(join(tools, 'package.json'))('ffmpeg-static'); } catch { /* fall through */ } }
  return 'ffmpeg';
}
const ffmpeg = findFfmpeg();

// ---- sound design (all synthesized) ----
const ms = (t) => Math.max(0, Math.round(t));
const sfx = []; // { t, src (lavfi), chain (filters after the source) }
const add = (t, src, chain) => sfx.push({ t: ms(t), src, chain });
const members = Object.fromEntries(script.meta.members.map((m) => [m.id, m]));
for (const e of ev) {
  if (e.type === 'message') {
    const bot = members[e.from]?.bot;
    // Homi: a bright two-partial "tick"; people: a softer, lower "pop".
    if (bot) add(e.t, 'sine=frequency=1480:duration=0.12', 'afade=t=out:st=0.01:d=0.11,volume=0.22');
    else if (e.from === 'you') add(e.t, 'sine=frequency=740:duration=0.1', 'afade=t=out:st=0.01:d=0.09,volume=0.2');
    else add(e.t, 'sine=frequency=620:duration=0.1', 'afade=t=out:st=0.01:d=0.09,volume=0.17');
    if (e.typing && !bot) add(e.t - e.typing, 'anoisesrc=duration=0.25:color=brown:seed=7', 'highpass=f=2500,afade=t=in:d=0.05,afade=t=out:st=0.1:d=0.15,volume=0.05');
  } else if (e.type === 'reaction') {
    add(e.t, 'sine=frequency=1960:duration=0.07', 'afade=t=out:st=0.005:d=0.065,volume=0.12');
  } else if (e.type === 'jump') {
    add(e.t, `anoisesrc=duration=${(e.duration / 1000).toFixed(2)}:color=pink:seed=3`, `lowpass=f=1400,afade=t=in:d=0.25,afade=t=out:st=${((e.duration / 1000) * 0.45).toFixed(2)}:d=${((e.duration / 1000) * 0.55).toFixed(2)},volume=0.28`);
  } else if (e.type === 'dm') {
    add(e.t, 'anoisesrc=duration=0.45:color=pink:seed=5', 'highpass=f=600,afade=t=in:d=0.12,afade=t=out:st=0.2:d=0.25,volume=0.22');
    add(e.t + e.duration - 380, 'anoisesrc=duration=0.4:color=pink:seed=6', 'highpass=f=600,afade=t=in:d=0.1,afade=t=out:st=0.15:d=0.25,volume=0.18');
  } else if (e.type === 'pulse') {
    // a warm two-note chime
    add(e.t, 'sine=frequency=660:duration=1.1', 'afade=t=out:st=0.05:d=1.05,volume=0.16');
    add(e.t + 90, 'sine=frequency=990:duration=1.0', 'afade=t=out:st=0.05:d=0.95,volume=0.12');
  } else if (e.type === 'stat') {
    add(e.t, 'anoisesrc=duration=1.3:color=pink:seed=9', 'lowpass=f=900,afade=t=in:d=1.0,afade=t=out:st=1.0:d=0.3,volume=0.25');
    add(e.t + 1150, 'sine=frequency=1320:duration=0.6', 'afade=t=out:st=0.02:d=0.58,volume=0.14');
  } else if (e.type === 'title') {
    add(e.t + 150, 'sine=frequency=440:duration=1.6', 'afade=t=in:d=0.1,afade=t=out:st=0.4:d=1.2,volume=0.1');
    add(e.t + 150, 'sine=frequency=660:duration=1.6', 'afade=t=in:d=0.1,afade=t=out:st=0.4:d=1.2,volume=0.08');
  } else if (e.type === 'end') {
    add(e.t + 200, 'sine=frequency=440:duration=2.2', 'afade=t=in:d=0.2,afade=t=out:st=0.6:d=1.6,volume=0.1');
    add(e.t + 200, 'sine=frequency=554:duration=2.2', 'afade=t=in:d=0.2,afade=t=out:st=0.6:d=1.6,volume=0.08');
    add(e.t + 200, 'sine=frequency=659:duration=2.2', 'afade=t=in:d=0.2,afade=t=out:st=0.6:d=1.6,volume=0.07');
  }
}

// Pad: a slow A-minor-ish drone with detuned partials and a breathing tremolo, muted and ducked under the voice.
const T = (TOTAL / 1000).toFixed(2);
const padExpr = "'(sin(2*PI*110*t)+sin(2*PI*110.6*t)+0.7*sin(2*PI*164.8*t)+0.5*sin(2*PI*220*t)+0.35*sin(2*PI*261.6*t)+0.25*sin(2*PI*329.6*t))*(0.75+0.25*sin(2*PI*0.07*t))*0.12'";

function mux(layout, audioOnly) {
  const L = { vertical: 'homi-phone-1080x1920.mp4', landscape: 'homi-demo-1920x1080.mp4' }[layout];
  const video = join(ROOT, 'out', L);
  if (!audioOnly && !existsSync(video)) throw new Error('missing ' + video);
  const inputs = audioOnly ? [] : ['-i', video];
  const f = [];
  let n = audioOnly ? 0 : 1;
  const voLabels = [];
  for (const l of lines) {
    inputs.push('-i', l.file);
    f.push(`[${n}:a]aformat=sample_rates=48000:channel_layouts=stereo,adelay=${l.start}|${l.start},volume=1.5[vo${n}]`);
    voLabels.push(`[vo${n}]`);
    n++;
  }
  const sfxLabels = [];
  sfx.forEach((s, i) => {
    inputs.push('-f', 'lavfi', '-i', s.src);
    f.push(`[${n}:a]${s.chain},aformat=sample_rates=48000:channel_layouts=stereo,adelay=${s.t}|${s.t}[sx${i}]`);
    sfxLabels.push(`[sx${i}]`);
    n++;
  });
  inputs.push('-f', 'lavfi', '-i', `aevalsrc=${padExpr}:s=48000:d=${T}`);
  f.push(`[${n}:a]aformat=sample_rates=48000:channel_layouts=stereo,lowpass=f=1200,afade=t=in:d=2,afade=t=out:st=${(TOTAL / 1000 - 3).toFixed(2)}:d=3,volume=0.3[pad]`);
  n++;
  f.push(`${voLabels.join('')}amix=inputs=${voLabels.length}:duration=longest:normalize=0[vomix]`);
  f.push(`${sfxLabels.join('')}amix=inputs=${sfxLabels.length}:duration=longest:normalize=0[sfxmix]`);
  f.push('[vomix]asplit=2[vo_a][vo_b]');
  f.push('[pad][vo_b]sidechaincompress=threshold=0.015:ratio=8:attack=40:release=600:makeup=1[padd]');
  f.push(`[vo_a][sfxmix][padd]amix=inputs=3:duration=first:normalize=0,apad=whole_dur=${T},atrim=0:${T},alimiter=limit=0.92:level=false[out]`);
  if (audioOnly) {
    const r = spawnSync(ffmpeg, ['-y', '-hide_banner', '-loglevel', 'error', ...inputs, '-filter_complex', f.join(';'), '-map', '[out]', audioOnly], { stdio: 'inherit' });
    if (r.status !== 0) throw new Error('ffmpeg failed (audio only)');
    console.log(`audio only: ${lines.length} voice lines, ${sfx.length} sounds -> ${audioOnly}`);
    return;
  }
  const tmp = video.replace(/\.mp4$/, '.audio.mp4');
  const r = spawnSync(ffmpeg, ['-y', '-hide_banner', '-loglevel', 'error', ...inputs, '-filter_complex', f.join(';'),
    '-map', '0:v', '-map', '[out]', '-c:v', 'copy', '-c:a', 'aac', '-b:a', '192k', '-movflags', '+faststart', tmp], { stdio: 'inherit' });
  if (r.status !== 0) throw new Error('ffmpeg failed for ' + layout);
  unlinkSync(video);
  renameSync(tmp, video);
  console.log(`[${layout}] audio muxed: ${lines.length} voice lines, ${sfx.length} sounds, pad ducked under the voice -> ${video}`);
}

// --audio-only=<file.wav>: just the mix, to check the graph and levels without touching the videos
if (args['audio-only']) mux('vertical', String(args['audio-only']));
else for (const layout of args.only ? [args.only] : ['vertical', 'landscape']) mux(layout);
